    const p = document.querySelector('#password');
    if (u) setNativeValue(u, 'standard_user');
    if (p) setNativeValue(p, 'secret_sauce');

    setTimeout(() => {
        document.querySelector('#login-button')?.click();
    }, 200);
})()
